//! Gateway help selected when the modal is rendered.
use vw_config_types::ui::DesktopLocale;
pub fn gateway(locale: DesktopLocale) -> &'static str {
    match locale {
        DesktopLocale::SimplifiedChinese => {
            "服务端网关配置说明\n\n一、监听与暴露\n- gateway.port / gateway.host 控制 HTTP gateway 的监听地址。\n- allow_public_bind 默认关闭，防止在无隧道/代理保护的情况下直接暴露公网。\n\n二、安全与 skey\n- auth_enabled 开启后，客户端需通过 Authorization: Bearer <skey> 访问受保护端点。\n- 新增 skey 时只填写名称和可选过期日期；原始 skey 自动生成且仅展示一次。\n- skeys 只保存 enabled、skey_hash、脱敏 skey、名称和过期时间，原始 skey 不会写入配置。\n- 单个 skey 可禁用；禁用后不会通过鉴权。\n- trust_forwarded_headers 仅应在可信反向代理后开启。\n\n三、限流与幂等\n- webhook_rate_limit_per_minute 控制 webhook 每分钟请求上限。\n- rate_limit_max_keys 控制内存中追踪的客户端 key 数量。\n- idempotency_ttl_secs / idempotency_max_keys 控制 webhook 幂等缓存行为。\n\n四、Node Control\n- node_control.enabled 打开实验性 node-control API。\n- node_control.auth_token 为额外共享令牌，客户端需通过 X-Node-Control-Token 传递。\n- node_control.allowed_node_ids 为空表示不显式限制；可使用 * 允许所有节点。\n\n五、推荐默认\n- host 使用 127.0.0.1。\n- auth_enabled 默认关闭；对外暴露前再开启并配置 skey。\n- allow_public_bind 保持关闭。\n- trust_forwarded_headers 仅在受控代理链路后启用。"
        }
        DesktopLocale::TraditionalChinese => {
            "服務端網關配置說明\n\n一、監聽與暴露\n- gateway.port / gateway.host 控制 HTTP gateway 的監聽地址。\n- allow_public_bind 默認關閉，防止在無隧道/代理保護的情況下直接暴露公網。\n\n二、安全與 skey\n- auth_enabled 開啓後，客戶端需通過 Authorization: Bearer <skey> 訪問受保護端點。\n- 新增 skey 時只填寫名稱和可選過期日期；原始 skey 自動生成且僅展示一次。\n- skeys 只保存 enabled、skey_hash、脫敏 skey、名稱和過期時間，原始 skey 不會寫入配置。\n- 單個 skey 可禁用；禁用後不會通過鑒權。\n- trust_forwarded_headers 僅應在可信反向代理後開啓。\n\n三、限流與冪等\n- webhook_rate_limit_per_minute 控制 webhook 每分鐘請求上限。\n- rate_limit_max_keys 控制內存中追蹤的客戶端 key 數量。\n- idempotency_ttl_secs / idempotency_max_keys 控制 webhook 冪等緩存行為。\n\n四、Node Control\n- node_control.enabled 打開實驗性 node-control API。\n- node_control.auth_token 為額外共享令牌，客戶端需通過 X-Node-Control-Token 傳遞。\n- node_control.allowed_node_ids 為空表示不顯式限制；可使用 * 允許所有節點。\n\n五、推薦默認\n- host 使用 127.0.0.1。\n- auth_enabled 默認關閉；對外暴露前再開啓並配置 skey。\n- allow_public_bind 保持關閉。\n- trust_forwarded_headers 僅在受控代理鏈路後啓用。"
        }
        DesktopLocale::English => {
            "Server Gateway settings\n\nListen address and exposure\n- gateway.host / gateway.port control the HTTP listen address.\n- allow_public_bind defaults to false to prevent exposure without a proxy or tunnel.\n\nSecurity and skey\n- auth_enabled requires Authorization: Bearer <skey> for protected endpoints.\n- Enter a name and optional expiration date to generate a skey. The original key is shown only once.\n- skeys stores enabled, skey_hash, masked skey, name and expiration. Original keys are never stored.\n- Disabled skeys cannot authenticate requests.\n- Enable trust_forwarded_headers only behind a trusted reverse proxy.\n\nRate limits and idempotency\n- webhook_rate_limit_per_minute limits webhook requests per minute.\n- rate_limit_max_keys limits tracked client keys in memory.\n- idempotency_ttl_secs / idempotency_max_keys control webhook idempotency caching.\n\nNode Control\n- node_control.enabled enables the experimental node-control API.\n- node_control.auth_token is an additional shared token sent as X-Node-Control-Token.\n- Empty node_control.allowed_node_ids means no explicit allowlist; * allows all nodes.\n\nRecommended defaults\n- Use host 127.0.0.1.\n- auth_enabled defaults to false; configure skeys and enable authentication before exposing the service.\n- Keep allow_public_bind disabled.\n- Trust forwarded headers only in a controlled proxy chain."
        }
    }
}
pub fn gateway_client(locale: DesktopLocale) -> &'static str {
    match locale {
        DesktopLocale::SimplifiedChinese => {
            "客户端网关配置说明\n\n一、作用\n- 这里配置桌面端发请求时要连接的 Gateway 地址、租户与认证信息。\n- 支持多个 Gateway 服务；当前选中的服务会成为 Desktop 的客户端请求目标。\n- 这些设置不会修改服务端网关的监听配置。\n\n二、字段含义\n1) host\n- 目标 Gateway 主机地址，默认 127.0.0.1。\n\n2) port\n- 目标 Gateway 端口，默认 14682。\n\n3) platform_id / company_id\n- 平台与公司租户 ID，默认 10000 / 100000000；不能为空。\n\n4) skey\n- 可选 skey。填写后会作为 Authorization: Bearer <skey> 发送给网关。\n\n三、示例\n{\n  \"gateway_client\": {\n    \"active_server_id\": \"local\",\n    \"servers\": [\n      {\n        \"id\": \"local\",\n        \"name\": \"本地网关\",\n        \"host\": \"127.0.0.1\",\n        \"port\": 14682,\n        \"platform_id\": \"10000\",\n        \"company_id\": \"100000000\",\n        \"skey\": \"\"\n      }\n    ],\n    \"host\": \"127.0.0.1\",\n    \"port\": 14682,\n    \"platform_id\": \"10000\",\n    \"company_id\": \"100000000\",\n    \"skey\": \"\"\n  }\n}\n"
        }
        DesktopLocale::TraditionalChinese => {
            "客戶端網關配置說明\n\n一、作用\n- 這裡配置桌面端發請求時要連接的 Gateway 地址、租戶與認證信息。\n- 支持多個 Gateway 服務；當前選中的服務會成為 Desktop 的客戶端請求目標。\n- 這些設置不會修改服務端網關的監聽配置。\n\n二、字段含義\n1) host\n- 目標 Gateway 主機地址，默認 127.0.0.1。\n\n2) port\n- 目標 Gateway 端口，默認 14682。\n\n3) platform_id / company_id\n- 平台與公司租戶 ID，默認 10000 / 100000000；不能為空。\n\n4) skey\n- 可選 skey。填寫後會作為 Authorization: Bearer <skey> 發送給網關。\n\n三、示例\n{\n  \"gateway_client\": {\n    \"active_server_id\": \"local\",\n    \"servers\": [\n      {\n        \"id\": \"local\",\n        \"name\": \"本地网关\",\n        \"host\": \"127.0.0.1\",\n        \"port\": 14682,\n        \"platform_id\": \"10000\",\n        \"company_id\": \"100000000\",\n        \"skey\": \"\"\n      }\n    ],\n    \"host\": \"127.0.0.1\",\n    \"port\": 14682,\n    \"platform_id\": \"10000\",\n    \"company_id\": \"100000000\",\n    \"skey\": \"\"\n  }\n}\n"
        }
        DesktopLocale::English => {
            "Client Gateway settings\n\nPurpose\n- Configure the Gateway address, tenant and credentials used by Desktop requests.\n- Multiple Gateway services are supported. Requests use the selected service.\n- These settings do not change the server listen configuration.\n\nFields\n- host: target Gateway host, default 127.0.0.1.\n- port: target Gateway port, default 14682.\n- platform_id / company_id: required platform and company tenant IDs, default 10000 / 100000000.\n- skey: optional credential sent as Authorization: Bearer <skey>.\n\nExample\n{\n  \"gateway_client\": {\n    \"active_server_id\": \"local\",\n    \"servers\": [\n      {\n        \"id\": \"local\",\n        \"name\": \"本地网关\",\n        \"host\": \"127.0.0.1\",\n        \"port\": 14682,\n        \"platform_id\": \"10000\",\n        \"company_id\": \"100000000\",\n        \"skey\": \"\"\n      }\n    ],\n    \"host\": \"127.0.0.1\",\n    \"port\": 14682,\n    \"platform_id\": \"10000\",\n    \"company_id\": \"100000000\",\n    \"skey\": \"\"\n  }\n}\n"
        }
    }
}
